/* Yoopanese display strings for the Cozy War ladder (150 tiers), keyed by the exact
 * English label in COZY_WAR_TIERS. Display-only: scoring always uses the English tiers. */
window.YOOPER = window.YOOPER || {};
window.YOOPER.COZY_WAR_TIERS = Object.assign(window.YOOPER.COZY_WAR_TIERS || {}, {
 "Sent Outside": {
  "label": "Sent Outside, Eh",
  "desc": "No rain, so no excuse, eh. At 10:04 a parent announces it's a beautiful day, an' both kids on da couch get sent outside for at least 45 minutes. Da blanket gets folded, da 4 cushions go back on da sofa, an' da war's called postponed, not lost. It's 72°F an' nobody's happy about it."
 },
 "Wet Grass Claim": {
  "label": "Da Wet Grass Claim",
  "desc": "At 7:15 da lawn's wet, an' da younger one, age 7, files a claim dat it rained overnight. Da claim gets looked at by da back door an' denied, 'cause dew isn't weather. One sock's soaked right through to da second toe an' goes into evidence. Da appeal gets heard after breakfast an' takes under 2 minutes."
 },
 "One Cushion": {
  "label": "One Cushion, Yah",
  "desc": "One sofa cushion, 24 by 24 by 5 inches, comes off da couch an' goes on da floor as a forward position. It holds one kid an' one stuffed bear. A parent points out it isn't rainin' an' puts da cushion back at 8:02. It comes off again at 8:03."
 },
 "The Blanket": {
  "label": "Da Blanket",
  "desc": "Da Blanket gets issued. It's a 50-by-60-inch green fleece throw wit' one corner chewed by a dog, an' it's lived on da back of da recliner for 3 years. Draped over one cushion it makes a lean-to wit' 2 square feet of floor space. Da dog, who chewed dat corner, doesn't get asked."
 },
 "Porch Inspection": {
  "label": "Porch Inspection, Eh",
  "desc": "At 9:30 da younger one inspects da porch railin' an' finds 11 droplets, none of 'em fallin'. A report gets drafted in crayon sayin' droplets are just rain dat quit. Da report's 1 page long an' spells droplets 3 different ways. It gets filed under da couch."
 },
 "Lean-To Holdout": {
  "label": "Da Lean-To Holdout",
  "desc": "Da lean-to under da Blanket gets held for 40 minutes against nobody at all. Da kid inside eats 1 granola bar, drinks 6 ounces of apple juice, an' calls da position secure. A parent steps over it 4 times on da way to da laundry room an' never once calls it a structure, ya know."
 },
 "Window Fog": {
  "label": "Window Fog, Eh",
  "desc": "Mist shows up an' fogs da bottom 8 inches of da livin' room window. Da younger one writes RAIN in it wit' one finger, letters 3 inches tall, for da record. Da older one, age 11, looks it over from da doorway an' concedes nuttin'. Da fog's gone by 10:20 an' da word goes wit' it."
 },
 "Second Recruit": {
  "label": "Da Second Recruit",
  "desc": "Da older one, 11, joins da lean-to so long as da younger one, 7, scoots over. Two kids in 2 square feet is about 100 percent over da design load. Da lean-to caves in at da 90-second mark an' gets rebuilt da exact same way, an' dat one caves in too."
 },
 "Cushion Audit": {
  "label": "Da Cushion Audit",
  "desc": "Da couch gets a formal inventory: 2 seat cushions, 2 back cushions, an' 2 throw pillows, 6 pieces all togedder. Da inventory's written on a sticky note an' stuck on da TV screen. A parent pulls da note down at 11:05, an' both kids write dat down as da first censorship of da whole war."
 },
 "Sock Munitions": {
  "label": "Sock Munitions, Yah",
  "desc": "Ammo gets found. A laundry basket in da hall's got 14 balled-up pairs of socks at about 2 ounces each, heavy enough to let ya know ya got hit an' too light to do any harm. Da pile gets split 7 an' 7. Nobody fires, 'cause da basket's still technically folded laundry."
 },
 "First Volley": {
  "label": "Da First Volley",
  "desc": "At 11:40 da laundry gets declared unfolded. Da openin' volley's 3 socks thrown from 9 feet, an' 1 hits, right in da shoulder. Zero casualties. Da basket can't get folded back da way it was, so a parent gives da both of 'em 10 minutes of refoldin', an' it takes 'em 22."
 },
 "Lunch Truce": {
  "label": "Da Lunch Truce",
  "desc": "Lunch puts a truce in place. Da kitchen table's 60 inches long an' da two sides sit at opposite ends, which is just about exactly how far a grape can go. One grape gets thrown. Da truce gets stretched through dessert wit' a parent watchin', an' 4 cookies get handed out even, dat's 2 apiece."
 },
 "Mist Standoff": {
  "label": "Da Mist Standoff",
  "desc": "Mist keeps comin' at a rate no gauge can measure. Da two sides hold cushions facin' each udder 12 feet apart for 35 minutes, nobody movin', both callin' da udder one da aggressor. Da dog lies down right in da middle of no man's land, an' both sides call it neutral territory."
 },
 "Official Rain": {
  "label": "Official Rain, Eh",
  "desc": "Da first real drops hit da patio at about 1 per square foot per minute. Both kids watch from da slidin' door, an' da older one, 11, officially admits it's rainin'. Outside play's called off, inside war's authorized, an' da Blanket moves from da recliner to da front line at 1:12."
 },
 "Cereal Box Survey": {
  "label": "Da Cereal Box Survey",
  "desc": "An empty cereal box gets flattened on da kitchen floor to use for drawin' plans. Da back panel's about 8 by 12 inches, wit' a maze printed on it, an' da maze is off limits. Da survey of da livin' room takes 20 minutes an' figures out da couch is 84 inches wide an' da room's mostly couch."
 },
 "The Fort Plan": {
  "label": "Da Fort Plan",
  "desc": "Da Fort Plan gets drawn in pencil on da back of da cereal box: 4 cushions, 2 chairs, 1 blanket, 6 clothespins. Da 2 kitchen chairs, 34 inches at da back, stand 4 feet apart for uprights, da Blanket goes across 'em, an' da cushions make da walls. Both kids sign it. Da drawin' takes 25 minutes an' it's da most important paper dat house'll ever make."
 },
 "Clothespin Requisition": {
  "label": "Clothespin Requisition, Yah",
  "desc": "Da Fort Plan needs 6 clothespins, an' da house has got 6, every one of 'em on a bag of frozen peas. Da peas get closed up wit' a rubber band, an' dat goes in da log as a supply-chain compromise. Da requisition takes 4 minutes an' wraps up before da freezer door alarm goes off at da 5-minute mark."
 },
 "Groundbreaking": {
  "label": "Da Groundbreakin'",
  "desc": "Construction starts at 1:50. Da 2 chairs get set facin' each udder 48 inches apart, da Blanket goes over da top, an' 6 clothespins hold it at da corners an' da middles. Da finished inside is 48 by 30 inches wit' a 34-inch ceilin', an' it matches da Fort Plan exactly, holy wah."
 },
 "Ceiling Sag": {
  "label": "Da Ceilin' Sag",
  "desc": "Da fleece ceilin' sags 7 inches in da middle in da first 10 minutes, so a 7-year-old sittin' up has got zero headroom. A broom handle 54 inches long goes in as a ridge pole. It works, an' it's da first amendment to da Fort Plan, written in da margin real small."
 },
 "Pillow Skirmish": {
  "label": "Pillow Skirmish, Eh",
  "desc": "Da first pillow fight's over who gets to sit by da door. Both regular pillows, 20 by 26 inches, get used, an' 17 hits go back an' forth in about 90 seconds. Da fort loses 1 clothespin an' a wall cushion. Pillow casualties get written down as 2 bruised egos an' a lamp dat wobbled but stayed up."
 },
 "Cocoa Line": {
  "label": "Da Cocoa Line",
  "desc": "Da first supply run brings 2 mugs of cocoa microwaved up to about 160°F. Ya s'posed to let 'em cool 6 minutes, an' both mugs get watched every second of it. Da younger one tries a sip at minute 3 an' reports da tongue a little damaged but still in service."
 },
 "Marshmallow Ration": {
  "label": "Da Marshmallow Ration",
  "desc": "Da marshmallows get counted before handin' out: 23 in da bag. Da older one says 12 an' 11, by age. Da younger one says 12 an' 11 da udder way. A parent settles it by eatin' da extra one, dat leaves 11 each, an' both sides call it a loss of sovereignty."
 },
 "Drizzle Doctrine": {
  "label": "Da Drizzle Doctrine",
  "desc": "Steady drizzle starts an' da kids adopt da Drizzle Doctrine: nobody leaves da fort while ya can hear da rain. Da doctrine gets suspended 3 times in da first hour for bathroom trips an' once for a snack. Da doorway, a pillowcase 20 by 26 inches hung off da ridge pole, gets logged open an' shut every time."
 },
 "Flashlight Code": {
  "label": "Da Flashlight Code",
  "desc": "A flashlight gets issued wit' 2 AA batteries an' a code of 3 signals: 1 flash for cocoa, 2 for danger, 3 for parent comin'. By 3:10 da code's been used 41 times, an' 38 of dose were for cocoa. Da batteries are figured to have about 4 more hours in 'em."
 },
 "Couch Annexation": {
  "label": "Da Couch Annexation",
  "desc": "Da couch frame, wit' no cushions left on it, gets annexed as a second structure, a bare deck 84 by 30 inches. It's da observation platform now. A parent sits on it at 3:30, sinks 4 inches into da springs, an' leaves da area wit'out a word after 2 minutes."
 },
 "Hallway Checkpoint": {
  "label": "Da Hallway Checkpoint",
  "desc": "Da hallway, 36 inches wide an' 14 feet long, gets declared a controlled corridor. A checkpoint of 2 throw pillows goes in da middle, an' ya need a password to get by dat changes every 15 minutes. At 3:45 da kid who made up da password forgets it, an' da corridor's closed to everybody, dat kid included."
 },
 "Board Game Treaty": {
  "label": "Board Game Treaty, Yah",
  "desc": "Da fightin' stops for a board game made for 2 to 4 players. Da game goes 70 minutes, an' da treaty, written on da back of da score sheet, gives da winner first pick of fort spots for 1 whole day. Da loser disputes da last roll, a 6, 'cause it went off da table an' got read under da couch by flashlight."
 },
 "Treaty Violation": {
  "label": "Da Treaty Violation",
  "desc": "Da treaty lasts 26 minutes. Da winner takes first pick of spots, da loser sits dere anyway, an' 9 socks get fired in da fight dat follows. Da score sheet gets torn into 2 halves, one for each side, an' each side says dere half is da original."
 },
 "Dog Neutrality": {
  "label": "Da Dog Stays Neutral",
  "desc": "Da dog walks into da fort an' sits on da Blanket, right on da chewed corner, like it's comin' back to da scene. Both sides try to recruit it wit' 5 crackers between 'em. It takes all 5, joins nobody, an' takes up 40 percent of da 48-by-30-inch floor for da next hour."
 },
 "Linen Closet Raid": {
  "label": "Da Linen Closet Raid",
  "desc": "A light shower sets in, finally measurable in hundredths of an inch, an' da war outgrows 1 blanket. A raid on da linen closet turns up a queen blanket, 90 by 90 inches, an' 2 bath towels. Da new one covers about 56 square feet, roughly 2.7 times da Blanket, but da Blanket stays da flag an' never gets demoted."
 },
 "Annex Construction": {
  "label": "Da Annex",
  "desc": "Da queen blanket gets stretched from da fort to da couch frame, addin' an annex 6 by 7 feet. It needs 4 more supports an' da house has got 2 spare kitchen chairs, so da rest is a laundry basket an' an ottoman 18 inches tall. Da annex comes down at 4:20 an' gets rebuilt wit' books for ballast."
 },
 "Book Ballast": {
  "label": "Da Book Ballast",
  "desc": "Eleven hardcovers, about 2 pounds apiece, get laid on da edges of da queen blanket where it crosses da chair seats, 22 pounds of books all togedder. Nobody reads any of 'em. Da heaviest one, a dictionary of about 4 pounds, holds down da corner by da door, an' from den on it's called da keystone."
 },
 "Lamp Protocol": {
  "label": "Da Lamp Protocol",
  "desc": "A floor lamp 60 inches tall turns out to be inside da annex. It gets named a protected structure, an' nobody's allowed to hit it wit' a pillow, a sock, or an elbow. Da protocol gets broke 2 times in 30 minutes, da shade tippin' 15 degrees each time, an' a parent quietly moves da lamp to da dinin' room."
 },
 "Cocoa Convoy": {
  "label": "Da Cocoa Convoy",
  "desc": "Da second cocoa run's set up as a convoy, 2 mugs carried 22 feet from da kitchen, through da hallway checkpoint, to da annex. It takes 50 seconds an' about 1 ounce gets lost on da carpet, so a towel goes over it like ya s'posed to. Da 6-minute coolin' time gets kept again, every bit of it."
 },
 "Rain on the Roof": {
  "label": "Rain on da Roof",
  "desc": "Ya can hear da rain on da roof once da day's total gets past a tenth of an inch, an' morale goes up. Da kids lie in da fort for 12 minutes doin' nuttin' but listenin' to it, an' dat's logged as a strategic pause. Da flashlight gets switched off to save its 2 batteries, an' da room goes da gray of 5 o'clock."
 },
 "Sibling Pact": {
  "label": "Da Sibling Pact",
  "desc": "A mutual defense pact gets signed against da last grown-up threat left, bedtime, set for 8:30 right now. Both kids agree to stick togedder, ask for 30 more minutes, an' blame da rain. Da pact's written in marker on an index card 3 by 5 inches an' tucked under da Blanket's chewed corner for safekeepin'."
 },
 "Dinner Evacuation": {
  "label": "Da Supper Evacuation",
  "desc": "Supper needs all 4 kitchen chairs, an' 2 of dem are load-bearin'. Da negotiatin' goes 8 minutes an' ends in a controlled evacuation: da fort ceilin' gets lowered onto da couch frame an' 11 books, an' da chairs report to da table. Supper lasts 19 minutes, fastest meal on record in dat house, an' it was pasties."
 },
 "Night Operations": {
  "label": "Night Operations, Eh",
  "desc": "Da rain turns steady after dark an' da fort goes back up at 7:05. Night operations run on 1 flashlight an' a string of 50 Christmas lights out of a box in da garage, plugged in 12 feet away wit' da cord run along da baseboard. Da dog's found sleepin' inside at 7:40 an' gets to stay as a guest of da state."
 },
 "Bedtime Siege": {
  "label": "Da Bedtime Siege",
  "desc": "At 8:30 da pact gets invoked. Both kids ask for 30 more minutes, pointin' at 0.18 inches of rain, an' get 15. Da fort's ordered down by 9:00, an' da 6 clothespins go back on da peas, which made it 7 hours in a rubber band wit'out any trouble."
 },
 "Second Day": {
  "label": "Da Second Day",
  "desc": "Rain keeps goin' into a second day, drippin' off da gutter about 1 drop a second at da downspout. Da Fort Plan gets rescued out of da recyclin' bin, where it got tossed by mistake at 9:14 da night before, an' da fort gets rebuilt off it in 11 minutes flat. Da veterans say da first build took 3 times as long."
 },
 "Bedroom Front": {
  "label": "Da Bedroom Front",
  "desc": "Da war moves upstairs. Da older one's bedroom, 10 by 12 feet, turns into a second front wit' a bunker made of da mattress an' da desk chair. Da 2 fronts are 26 steps apart, 14 of 'em stairs, an' dey talk by flashlight from da landin' usin' da 3-signal code, which picks up a fourth signal meanin' come here but no hurry."
 },
 "Mattress Wall": {
  "label": "Da Mattress Wall",
  "desc": "Steady rain shows up an' da war gets heavy armor. A twin mattress, 38 by 75 inches an' about 40 pounds, gets dragged out of da bedroom an' stood on edge in da hallway for a wall. Da move takes both kids 6 minutes an' knocks 1 framed picture off da wall on da way. Da picture gets hung back up 5 degrees crooked an' nobody ever brings it up."
 },
 "Pillow Census": {
  "label": "Da Pillow Census",
  "desc": "A full pillow census gets taken: 9 pillows in da house, 4 regular ones at 20 by 26 inches, 2 kings at 20 by 36, 2 throw pillows, an' 1 fancy one nobody's allowed to touch. Da fancy one goes under diplomatic protection. Da udder 8 get split 4 an' 4, an' each side names a quartermaster, who's also its whole army."
 },
 "Battle of the Landing": {
  "label": "Battle of da Landin'",
  "desc": "Da Battle of da Landin' gets fought at 2:15 across da 8-foot upstairs hall. It lasts 4 minutes, wit' 8 pillows, 31 hits, an' 1 king pillow thrown overhand dat got ruled excessive later. Losses are 1 pillowcase seam, 1 stuffed rabbit knocked down da stairs, an' 0 injuries. Both sides claim da landin', cripes."
 },
 "The Recruit": {
  "label": "Da Recruit",
  "desc": "A neighbor kid, age 9, shows up at 10:00 under an umbrella, carryin' a sleepin' bag an' 1 backpack. Now da house has got 3 fighters an' a question of who gets da recruit. Da recruit settles it by pickin' da side wit' da flashlight, an' da udder side fires 2 socks at da door in protest."
 },
 "Sleeping Bag Tunnel": {
  "label": "Da Sleepin' Bag Tunnel",
  "desc": "Da recruit's sleepin' bag, 33 by 72 inches unzipped, goes under da kitchen table to make a tunnel from da livin' room fort to da kitchen. Da table's 60 inches long, so 6 inches of bag stick out each end, an' dose are called da portals. Da dog uses da tunnel 6 times in da first hour an' doesn't get charged a toll."
 },
 "Three-Room Fort": {
  "label": "Da Three-Room Fort",
  "desc": "Da rain gets past half an inch an' da fort takes up 3 rooms, da livin' room, da hallway, an' da dinin' room, about 420 square feet of floor. In service: 4 cushions, 4 chairs, 3 blankets, 1 mattress, 1 sleepin' bag, an' every clothespin in da house, which is still 6. Da floor plan gets redrawn on a 2nd cereal box."
 },
 "Laundry Day Crisis": {
  "label": "Laundry Day Crisis, Eh",
  "desc": "Wash day comes an' a parent takes back 3 blankets an' 14 pairs of socks for da washer, which runs 58 minutes a load. Da front loses its whole sock arsenal an' 2 of its ceilin's. Da Blanket gets an exemption, 'cause it got washed 9 days ago an' it's da flag."
 },
 "Dryer Warmth": {
  "label": "Da Dryer Warmth",
  "desc": "Da first load comes out of da dryer at about 135°F an' gets carried to da fort in a basket. Everybody lies under warm blankets for 18 minutes, longest ceasefire of da whole war, while da fabric cools down toward da house's 70°F. Both sides agree later dat da dryer's da most powerful weapon in da house, warmer'n a sauna bench, an' it don't belong to either one of 'em."
 },
 "Walkie-Talkie Net": {
  "label": "Da Walkie-Talkie Net",
  "desc": "Rain gets up near an inch an' inside fronts open up across da street. Parents in 4 houses set up a rotation at 11:30, an' by noon da 5 kids in it are tradin' intelligence by walkie-talkie on channel 3. Range is about 300 feet, enough to reach 2 houses an' a garage, an' every call ends wit' over, even da ones dat are just da word over."
 },
 "Sleepover Declared": {
  "label": "Sleepover Declared, Yah",
  "desc": "Da rain hits an inch an' a sleepover gets declared at da house wit' da biggest livin' room, 16 by 20 feet. It's 4 kids, 4 sleepin' bags, an' 1 dog, an' da host parent sets lights-out for 10:00. Fort stuff comes over by car in 3 laundry baskets, but da Blanket rides separate in a backpack, like its rank calls for."
 },
 "Joint Command": {
  "label": "Da Joint Command",
  "desc": "Da 4 kids form a joint command an' elect da host kid, 10, commander, over da objections of da older one, 11, who gets named chief of cocoa. Da first joint order's a fort on da Fort Plan pattern, doubled: 8 cushions, 4 chairs, 2 blankets, 12 clothespins. It goes up in 22 minutes an' comes out 2 inches off square."
 },
 "Cocoa Pipeline": {
  "label": "Da Cocoa Pipeline",
  "desc": "Da chief of cocoa sets up a pipeline: 1 saucepan of 32 ounces makes 4 mugs of 8 ounces at about 160°F. Da line runs every 45 minutes. Da 6-minute coolin' rule gets enforced by kitchen timer, an' one kid who drank early goes on 1 round of probation, served wit' an ice cube."
 },
 "Basement Front": {
  "label": "Da Basement Front",
  "desc": "Downpour rain gets past an inch an' a half, an' da basement, a finished room of 400 square feet, opens up as a third front. A dehumidifier runs in da corner at 50 pints a day. A parent checks da floor drain every 30 minutes an' finds it dry, an' da fort goes up around da ping-pong table, 9 by 5 feet, which makes a real good roof."
 },
 "Two-House Accord": {
  "label": "Da Two-House Accord",
  "desc": "A second sleepover starts up across da street, 5 kids strong, an' da 2 houses, 140 feet apart, open diplomatic relations by walkie-talkie. Da terms take 50 minutes to work out: no raids in da rain, a shared pile of 30 marshmallows, an' each side recognizes da udder side's forts. Da Blanket gets hung in da front window as a flag of intent."
 },
 "Thunder Drill": {
  "label": "Da Thunder Drill",
  "desc": "A cloudburst shows up wit' thunder, an' both houses run da drill: count da seconds from flash to boom an' divide by 5 for miles. Da first count's 10 seconds, dat's 2 miles. At 3 seconds every kid goes to an inside room, da forts sit empty for 20 minutes, an' a board game gets played under da Blanket in a hallway 36 inches wide. Heikki Lunta'd be proud."
 },
 "Power Flicker": {
  "label": "Da Power Flicker",
  "desc": "Da power flickers twice an' goes out for 38 minutes. Fort command switches over to 3 flashlights an' 1 battery lantern, an' da cocoa pipeline shuts down 'cause da stove's electric. Morale gets measured by how many kids are under da Blanket, an' dat gets up to 6 in a space 50 by 60 inches, holy wah."
 },
 "Three-House Alliance": {
  "label": "Da Three-House Alliance",
  "desc": "Da rain tops 2.6 inches an' a third house joins up, so now it's a sleepover alliance of 14 kids across 3 livin' rooms an' 2 basements. Da charter's 1 page, front an' back, an' article 1 makes da Fort Plan da standard unit of construction: 4 cushions, 2 chairs, 1 blanket, an' 6 clothespins a fort. Fifteen forts get proposed an' 9 get built."
 },
 "Fortified House": {
  "label": "Da Fortified House",
  "desc": "Da host house gets fortified front door to back: 6 rooms, 1,100 square feet, 9 blankets, 22 cushions, an' every chair on da main floor. Ya get between rooms by tunnel only, crawlin' height 30 inches. Da parents get one approved route to da coffee maker, 26 feet long, an' dey get fined 1 marshmallow every time dey wander off it."
 },
 "Surge Watch Lockdown": {
  "label": "Surge Watch Lockdown, Eh",
  "desc": "Rain gets near 4 inches, da curbs run full, an' 3 sets of parents tell every kid to stay put in whatever house dey're in. Nobody crosses da street, where da gutter water's 5 inches deep an' movin'. Da 3 houses got 14 kids an' 22 forts between 'em, checkin' in by walkie-talkie every 15 minutes. In da host house da Fort Plan hangs framed on da mantel, an' da Blanket's coverin' da youngest, age 5."
 },
 "Upstairs Garrison": {
  "label": "Upstairs Garrison",
  "desc": "Da Flash Flood Warnin’ comes in at 9:40 at night an’ da whole household moves upstairs, which is da right call an’ also, turns out, a relocation of da front. Da upstairs hallway is 36 inches wide an’ 14 feet long, an’ 3 people, 2 pillows each, an’ 1 dog hold it now. Move to higher ground when water is rising, and never wait to see how high it gets. Da hallway fort gets declared operational at 9:52, eh."
 },
 "Linen Closet Requisition": {
  "label": "Linen Closet Requisition",
  "desc": "Da linen closet at da top of da stairs gets inventoried by flashlight: 7 towels, 4 pillowcases, 2 sheets, an’ 1 quilt dat was supposed to be fer company. All 14 items get requisitioned into da hallway fort. Da company quilt is 90 by 90 inches an’ covers da hallway twice over, so da extra gets folded into a bench. Nobody signs nuttin’, but a list gets kept on da back of an envelope, ya know."
 },
 "The Go-Bag Audit": {
  "label": "Da Go-Bag Audit",
  "desc": "Da county tells folks near da crick to be ready to leave, an’ everybody gets told to pack 1 bag. Da bags get audited at da kitchen table at 11:15 at night. Da grown-ups pack medications, phone chargers, an’ 3 days of clothes; da kids pack 2 pillows, 1 stuffed rabbit, an’ a flashlight wit’ no batteries. Da audit finds da pillows compliant an’ da flashlight a problem, so 4 batteries get issued."
 },
 "Neighbor Annex": {
  "label": "Neighbor Annex",
  "desc": "Da neighbors across da road live in a one-story house, so at 1:30 in da mornin’ dey come over wit’ 2 kids, 1 cat, an’ 3 pillows. Da hallway fort, rated fer 3 people, holds 7 now. A joint command gets formed at da top of da stairs, like two deer camps sharin’ one stove. Da cat gets assigned to nobody an’ sleeps on da company quilt anyway, which gets logged as an occupation."
 },
 "Cocoa Run Denied": {
  "label": "Cocoa Run Denied",
  "desc": "At 6:00 in da mornin’ somebody proposes drivin’ to da grocery store fer cocoa, an’ da proposal gets denied. Da road at da bottom of da hill has 8 inches of water movin’ across it, and a foot of moving water can float most cars. Turn around, don’t drown. So da cocoa supply gets recounted instead: 11 packets, enough to give 7 people 1 packet each wit’ 4 held back in reserve."
 },
 "Fellowship Hall Posting": {
  "label": "Fellowship Hall Postin’",
  "desc": "Da church up on da ridge, 60 feet above da crick, opens its basement fellowship hall as a shelter at 8:00 in da mornin’. It’s got 12 foldin’ tables, 96 foldin’ chairs, an’ a kitchen pass-through, same as every potluck. By noon 23 people are inside, an’ da first fort goes up from 2 tables pushed together wit’ a tablecloth over top. Da tablecloth is 52 by 114 inches an’ is technically on loan from da altar guild."
 },
 "Potluck Supply Line": {
  "label": "Potluck Supply Line",
  "desc": "Da church kitchen opens a supply line: 4 casseroles, 1 coffee urn, an’ 60 paper bowls of chili by 5:30 in da evenin’, plus a pan of pasties nobody ordered. Da fort under da tables gets reclassified as da dining annex after 9 kids eat inside it. A sign-up sheet fer fort occupancy goes up on da bulletin board wit’ 3 time slots. It’s full in 20 minutes, an’ da waitin’ list runs onto a second page."
 },
 "The Blanket Evacuates": {
  "label": "Da Blanket Evacuates",
  "desc": "A family comes up from da crick side in da back of a sheriff’s truck wit’ 2 bags, 1 dog, an’ Da Blanket, a 50-by-60-inch green fleece throw with one corner chewed by a dog. Dere basement took 30 inches of water overnight. Da Blanket was da only ting da youngest, age 7, wouldn’t leave behind. It’s dry, it’s in one piece, an’ inside 1 hour it’s da roof of da most requested fort in da whole hall."
 },
 "Standard Issue": {
  "label": "Standard Issue",
  "desc": "Da shelter’s first supply pallet shows up: 150 cots, 150 blankets, an’ a laminated card sayin’ it’s 1 blanket per evacuee. Da blankets are grey, 60 by 80 inches, an’ all da same, which ends 3 ownership disputes on arrival an’ starts 5 new ones by bedtime. A volunteer gets named Keeper of da Tally an’ marks every blanket handed out on a clipboard. Da count closes at 41 issued an’ 109 held back in reserve."
 },
 "Fort Plan, Cot Edition": {
  "label": "Fort Plan, Cot Edition",
  "desc": "Da youngest from da crick-side family pulls out Da Fort Plan, drawn on da back of a cereal box: 4 cushions, 2 chairs, 1 blanket, 6 clothespins. Da shelter’s got no cushions, so 4 cots stand in, set up on dere sides as walls to make a square 75 inches on a side. Two foldin’ chairs hold up da middle, Da Blanket goes on top, an’ 6 clothespins get borrowed off da church laundry line. Da counts stay exact, yah."
 },
 "Gymnasium Theater": {
  "label": "Gymnasium Theater",
  "desc": "Da middle school gym opens as da second shelter, wit’ a floor 94 by 50 feet an’ 180 cots in 12 rows of 15. Da bleachers, 8 tiers high, get declared high ground inside da high ground. By 9:00 at night da top tier is held by 11 kids wit’ donated pillows who won’t come down fer lights-out. Negotiations get opened by a volunteer holdin’ 1 cup of cocoa."
 },
 "The Bleacher Siege": {
  "label": "Da Bleacher Siege",
  "desc": "Da bleacher holdouts dig in like it’s deer camp. Dey got 14 pillows, 3 standard-issue blankets, an’ a clear line of sight across all 180 cots. Da volunteers hold da floor an’ da cocoa urn, which holds 40 cups an’ gets kept at 170 degrees. Da siege lasts 47 minutes. It ends when da urn gets moved 6 feet closer to da bleachers, an’ terms get signed on a paper napkin."
 },
 "Six-Inch Rule": {
  "label": "Six-Inch Rule",
  "desc": "A teenager proposes wadin’ down to da house to get a better pillow. Da proposal gets denied by 4 grown-ups all at once. Six inches of moving water can knock an adult down, and the street outside the house has 18 inches. Da teenager gets 2 donated pillows from da reserve bin instead, stacked, which da shelter rates about equal to 1 good pillow from home."
 },
 "Cot Row Numbering": {
  "label": "Cot Row Numberin’",
  "desc": "Mandatory evacuations start fer 3 neighborhoods, an’ da gym fills to 212 people by midnight. More cots show up an’ da rows get numbered wit’ masking tape, A through P, 16 rows in all. Every cot is exactly 75 by 25 inches, an’ a family of 4 gets 4 cots side by side, which makes, by accident, a platform 75 by 100 inches. Every family notices dat right away."
 },
 "Lost-and-Found Armory": {
  "label": "Lost-an’-Found Armory",
  "desc": "Da school’s lost-an’-found bin gets opened under supervision an’ turns out to hold 23 sweatshirts, 9 single choppers, 4 towels, an’ 1 sleepin’ bag nobody can explain. Da contents get declared a strategic reserve. Da sleepin’ bag, which unzips flat to 66 by 72 inches, gets handed out by lottery. Eighty-seven people enter. Da winner uses it fer a fort roof, an’ everybody else gets a sweatshirt as consolation."
 },
 "Guard Convoy": {
  "label": "Guard Convoy",
  "desc": "Mandatory evacuations stretch along da river, an’ da National Guard brings 400 more cots in 5 trucks. Da shelter network runs 3 sites now wit’ 610 evacuees. At da gym, 400 new cots set off a buildin’ boom, an’ 27 forts go up before da trucks even leave. A volunteer walks da rows wit’ a clipboard an’ says 1 blanket per person is still in effect, eh."
 },
 "Cardboard Partition Act": {
  "label": "Cardboard Partition Act",
  "desc": "Privacy partitions show up flat-packed: cardboard panels 48 inches high an’ 72 inches wide, 2 per family. Inside an hour, 30 of dem got folded into walls, 6 into a tunnel, an’ 1 into a sign dat says OCCUPIED. Da shelter manager puts out a memo sayin’ partitions are fer privacy, not fortification. Da memo gets taped to a partition, which den gets used as a fort door."
 },
 "Lights-Out Protocol": {
  "label": "Lights-Out Protocol",
  "desc": "Lights-out is at 10:00 at night, wit’ da gym turned down to 2 of its 24 overhead lights. Flashlight use after lights-out is limited to 3 minutes an’ has to point at da floor. Da fort in row K turns out to hold 5 kids readin’ by 4 flashlights pointed at da ceiling. Da flashlights get confiscated an’ come back at 7:00 in da mornin’, fully charged, from da same volunteer."
 },
 "Low-Water Bridge Ruling": {
  "label": "Low-Water Bridge Rulin’",
  "desc": "A resident asks to drive home fer da family’s own pillows, 9 miles out. Da route crosses 2 low-water bridges dat have been closed since yesterday. A foot of moving water can float most cars, and 2 feet can sweep away SUVs and trucks. Da request gets turned down, an’ 6 donated pillows get issued instead, graded by a volunteer on a 1-to-5 fluffiness scale."
 },
 "Intake Desk": {
  "label": "Intake Desk",
  "desc": "Rescue boats are workin’ da subdivisions, an’ people reach da intake desk at a rate of 1 every 4 minutes. Every one gets logged an’ gets a wristband, a cot number, an’ 1 dry blanket inside 90 seconds of da door. Da intake table is 8 feet long wit’ 3 volunteers behind it. Nobody comin’ in gets asked about fort affiliation till dey’ve had cocoa, which is da one rule da shelter never broke."
 },
 "Pillow Drive": {
  "label": "Pillow Drive",
  "desc": "A donation drive in da next county sends 1,200 pillows in 40 contractor bags. Dey get sorted on 6 tables into firm, medium, soft, an’ a fourth pile labeled suspicious. It’s 1 per evacuee, wit’ a waitin’ list fer a second. Da suspicious pile, 17 pillows total, gets quietly retired to fort-wall duty, where it does better den anybody expected."
 },
 "Quiet Hours Armistice": {
  "label": "Quiet Hours Armistice",
  "desc": "Pillow fights in da cot rows get suspended under a written armistice, from 10 at night to 7 in da mornin’. Violations get reviewed by a council of 5 kids an’ 2 volunteers who meet at da cocoa urn. In 3 nights da council hears 14 complaints an’ upholds 2. Da penalty both times is foldin’ 20 blankets fer da laundry run."
 },
 "The Lending Blanket": {
  "label": "Da Lendin’ Blanket",
  "desc": "Da Blanket becomes da shelter’s first heirloom by an informal vote, 61 to 0. Its owner, 6 an’ a half now, agrees to lend it out every night to whatever kid came in most recent. A sign-out sheet gets kept on da clipboard. Over 11 nights it covers 11 different kids, gets washed twice, an’ comes back every mornin’ folded in quarters, chewed corner up, like da rule says."
 },
 "Arena Floor": {
  "label": "Arena Floor",
  "desc": "Wit’ downtown floodin’ an’ da National Guard deployed, da county opens da hockey arena, da ice covered over wit’ insulated floorin’. Da floor holds 1,400 cots in a grid measured to da inch. Da arena gets kept at 71 degrees, which evacuees say is 4 degrees too cold fer sleepin’ an’ just right to build in. By da second night 212 forts are registered wit’ da front desk."
 },
 "Upper Deck Holdout": {
  "label": "Upper Deck Holdout",
  "desc": "Da bleacher siege comes back at arena size. Section 214 up in da upper deck, 31 rows high, gets taken by 26 teenagers wit’ 40 pillows an’ a folded cardboard partition fer a flag. Arena staff say da section has da warmest air in da buildin’, about 6 degrees above da floor. A treaty gives da teenagers da section in trade, as long as dey help unload 3 cot trucks every mornin’."
 },
 "Mat Castle": {
  "label": "Mat Castle",
  "desc": "Da arena kids’ area gets 18 foldin’ tumblin’ mats, every one 4 by 8 feet an’ 2 inches thick. By afternoon da mats are a castle wit’ 2 towers, 1 moat of donated stuffed animals, an’ a drawbridge made from a cot. A volunteer measures da inside at 64 square feet an’ posts a capacity sign dat says 9. Da sign gets obeyed, an’ a line forms at 7:00 every mornin’."
 },
 "Moat Stays Indoors": {
  "label": "Moat Stays Inside",
  "desc": "A proposal to run da moat out to da arena parkin’ lot, which has 14 inches of standin’ water, gets shot down in under 1 minute. Floodwater can carry sewage, fuel, and chemicals, and can hide downed power lines and open manholes. Kids stay out of it. Da moat stays inside, dry, an’ made of 73 stuffed animals, an’ a second moat of 38 gets approved to keep tings fair."
 },
 "Convention Hall Command": {
  "label": "Convention Hall Command",
  "desc": "A federal disaster declaration brings da convention center online as da regional shelter, wit’ 5,000 cots across 3 exhibit halls of 100,000 square feet each. Da cot rows get street names so folks can find dere way back from da showers. A fort registry gets kept in a binder 4 inches thick. Da first 900 entries get sorted by type: tent, tunnel, lean-to, an’ cot pyramid."
 },
 "Laundry Rotation": {
  "label": "Laundry Rotation",
  "desc": "Da regional shelter washes standard-issue blankets on a 3-day cycle, 1,700 a day, through 12 commercial washers runnin’ 18 hours. Every blanket goes back to its cot by tag number, an’ forts gotta come down before 6:00 in da mornin’ on laundry day. Compliance da first cycle is 41 percent. By da third cycle, families are takin’ ’em down at 5:45 an’ puttin’ ’em back up by 9, quicker den da laundry."
 },
 "Cot Row Post Office": {
  "label": "Cot Row Post Office",
  "desc": "Da row names work so good dat a postal service starts up. Mail between forts gets delivered twice a day by 8 volunteers under age 12, usin’ a route map coverin’ 47 named rows. Addresses go row, cot number, an’ fort name. Da first week da service handles 1,312 letters, 88 of dem formal complaints about pillows creepin’ across a cot line."
 },
 "Pet Wing Ruling": {
  "label": "Pet Wing Rulin’",
  "desc": "Wit’ da transit shut down an’ downtown impassable fer weeks, da shelter opens a pet wing wit’ crates enough to hold 340 animals. Owners can visit in 2-hour windows. A beagle in crate 117 ain’t allowed a blanket of its own no more, under a rule passed after 3 standard-issue blankets turned up with one corner chewed. Da beagle has appealed through its owner, age 8, an’ da appeal is pendin’."
 },
 "Standard Fort Code": {
  "label": "Standard Fort Code",
  "desc": "Da shelter adopts Da Fort Plan as its standard fort, to settle fights over floor space. Every family pod can build 1 fort to da original counts, 4 cushions, 2 chairs, 1 blanket, 6 clothespins, wit’ cots standin’ in as cushions an’ foldin’ chairs as chairs. Da footprint is capped at 75 by 75 inches. Inspectors check 300 forts a day, an’ da most common violation is a seventh clothespin."
 },
 "School Network": {
  "label": "School Network",
  "desc": "Da region’s schools turn into shelters, 14 of dem hooked up on one radio channel an’ one shared blanket ledger. A family movin’ from one school to anudder carries its blankets wit’ a transfer slip in triplicate. Over 10 days da ledger records 2,260 transfers an’ a net loss of 19 blankets, all traced to 1 school where da gym forts are rumored to have a second floor."
 },
 "Cocoa Logistics": {
  "label": "Cocoa Logistics",
  "desc": "Cocoa is a logistics line item now. Da region’s shelters go through 640 gallons a day, served out of 22 urns kept between 160 an’ 170 degrees. Every urn gets a volunteer an’ a laminated schedule. A marshmallow shortage on day 12 gets treated like a supply emergency an’ fixed in 5 hours by a bakery in a dry county, which sends 90 pounds, same as a church basement potluck would."
 },
 "Mega-Shelter": {
  "label": "Mega-Shelter",
  "desc": "Levees breach an’ da regional mega-shelter opens in a stadium complex, wit’ 12,000 cots on da field, da concourses, an’ 4 practice gyms. Da site gets organized into 30 districts, every one wit’ a district captain, a cocoa urn, an’ a lost-an’-found. Forts are allowed in all 30 districts. Da biggest, in district 17, spans 11 cots an’ has a waitin’ list, a mailbox, an’ minutes, just like da township board."
 },
 "Generator Briefing": {
  "label": "Generator Briefin’",
  "desc": "Families goin’ back to check on dere houses get briefed at da exit in groups of 20. Never run a generator indoors or in a garage, even with the door open; carbon monoxide can build to deadly levels in minutes. Stay out of any building with standing water until it is inspected. Back inside, da briefin’ also gets posted on 30 district boards an’ 1 fort door, at da fort’s own request."
 },
 "Mega-Shelter Pillow Census": {
  "label": "Big Shelter Pillow Census",
  "desc": "Da mega-shelter runs a pillow census an’ counts 13,406 pillows among 12,000 evacuees. Da extra 1,406 get investigated. Findings show 71 percent held in forts as structural material, 22 percent in use as extra beddin’, an’ 7 percent nobody can find. Da census recommends no action, on account of da forts bein’ load-bearin’ an’ da evacuees havin’ been through enough already."
 },
 "Blanket Marshals": {
  "label": "Blanket Marshals",
  "desc": "Quiet hours get enforced by blanket marshals, 60 volunteers in orange vests, every one coverin’ 200 cots, like hunter orange at deer camp. Marshals carry 1 flashlight, 1 clipboard, an’ 4 spare standard-issue blankets fer anybody found cold. Dey got no authority over forts but get consulted on every one of dem. On a normal night a marshal hands out 3 blankets, settles 2 border disputes, an’ gets invited into 9 forts."
 },
 "Cot-Side Birthday": {
  "label": "Cot-Side Birthday",
  "desc": "A kid turns 7 on day 19 of da shelter stay. District 12 puts on da party in a fort built from 6 cots an’ 14 standard-issue blankets. Da cake is a sheet cake cut in 48 pieces, an’ da line reaches across 3 districts. Da birthday kid gets 1 brand-new pillow, still in da plastic, which da shelter records as da most valuable ting handed out dat week."
 },
 "Interstate Transfer": {
  "label": "Interstate Transfer",
  "desc": "Past any record, da region can’t hold everybody no more, so 8,000 evacuees get bused to shelters in 4 udder states, some 600 miles off. Every bus carries 56 people an’ 56 blankets, 1 apiece. Da Blanket goes too, in a carry-on, wit’ a transfer slip attached. At da new shelter it gets unfolded da first night, an’ a waitin’ list forms before da cots are even made up."
 },
 "Inter-Shelter Treaty": {
  "label": "Inter-Shelter Treaty",
  "desc": "Da sendin’ shelters an’ da receivin’ shelters sign a blanket treaty coverin’ 23 sites. Any blanket travelin’ wit’ an evacuee keeps its home tag. Pillows get traded 1 fer 1 at da edge of every shelter’s parkin’ lot. Fort designs get recognized both ways, so a fort dat’s legal in one state is legal in all 5. Da treaty runs 11 pages an’ gets signed on a cot."
 },
 "Barricade Rule": {
  "label": "Barricade Rule",
  "desc": "A bus on da transfer route runs into a flooded underpass wit’ 3 barricades across it, an’ da driver waits 40 minutes fer a detour. Never drive around a road-closed barricade; the water beyond it is often deeper and faster than it looks. Da 52 passengers wait in dere seats. By da time da detour’s posted, 4 little forts are built across rows 9 through 12 out of coats an’ carry-on pillows."
 },
 "Shelter Almanac": {
  "label": "Shelter Almanac",
  "desc": "Day 30. A shelter almanac comes out on 1 sheet folded in 3, recordin’ dat da region’s shelters have handed out 41,000 blankets, 38,500 pillows, an’ 1.9 million cups of cocoa. Da almanac lists 1,250 registered forts an’ names da one occupied da longest: a cot-an’-tablecloth build in district 4, standin’ 27 days. It’s printed in 9,000 copies an’ mostly read inside forts."
 },
 "Metro Displacement": {
  "label": "Metro Displacement",
  "desc": "Da metro is shut down, an’ more den 300,000 people are displaced. Shelters open in 60 buildings, from church basements to a convention center holdin’ 10,000. Da blanket allocation stays 1 per evacuee an’ gets met on day 2, after 90 trucks roll in. Fort buildin’ is da first pastime to show up at every site, usually inside 6 hours of da doors openin’."
 },
 "Months, Not Days": {
  "label": "Months, Not Days",
  "desc": "Shelter stays stretch from weeks into months, an’ 22,000 families move into hotel rooms under a temporary housin’ program. A standard room is 325 square feet wit’ 2 beds, 4 pillows, an’ 1 closet shelf of extra blankets. Da first fort in every room goes up inside 3 hours an’ uses da hotel’s 2 armchairs as walls. Housekeepin’ gets asked, polite-like, to work around it."
 },
 "Homework Fort": {
  "label": "Homework Fort",
  "desc": "School starts back up in 14 shelter classrooms on day 45, an’ homework moves into da forts. Every fort gets 1 clip-on lamp an’ 1 foldin’ tray table, 18 by 24 inches. Homework gets finished in forts at a rate 9 points higher den out in da cot rows, which da shelter school board writes down wit’ no explanation. Da board votes 5 to 0 to give lamps to every fort."
 },
 "Muck-Out Orders": {
  "label": "Muck-Out Orders",
  "desc": "Families start muckin’ out dere houses on day 50, wit’ 1 shelter volunteer fer every 4 houses. Wear gloves and boots, and throw out anything soaked by floodwater that cannot be disinfected, including mattresses, pillows, and stuffed toys. Drywall gets cut out at least 12 inches above da water line to stop mold. Back at da shelter, 600 replacement pillows get handed out dat same night, 1 per kid comin’ back."
 },
 "Trailer Alliance": {
  "label": "Trailer Alliance",
  "desc": "A temporary housin’ site opens on a fairground wit’ 420 travel trailers in rows of 30, like da biggest deer camp ya ever seen. Every trailer has a dinette dat turns into a bed 40 by 72 inches, which turns again, by day 3, into a fort. Trailer rows 7 through 11 form an alliance an’ hold a joint fort inspection every Saturday. Da alliance charter is 1 page long an’ requires cocoa at every meetin’."
 },
 "The Blanket Logbook": {
  "label": "Da Blanket Logbook",
  "desc": "Da Blanket’s sign-out sheet has turned into a logbook of 2 volumes. It records 97 nights lent to 97 kids across 3 shelters, 2 states, an’ 1 hotel room. It’s been washed 31 times, an’ da chewed corner never got fixed, by unanimous decision. It’s still da 50-by-60-inch green fleece throw with one corner chewed by a dog, an’ it still goes back folded in quarters, corner up."
 },
 "Last Cot Folded": {
  "label": "Last Cot Folded",
  "desc": "Day 90. Da last shelter closes, an’ its final 212 cots get folded an’ stacked in 17 minutes. Before da gym gets handed back, da families still dere build Da Fort Plan one last time at center court: 4 cots fer cushions, 2 foldin’ chairs, Da Blanket, an’ 6 clothespins. It stands 1 hour. Den Da Blanket gets folded in quarters an’ goes home wit’ its family, to a house rebuilt wit’ 14 sheets of new drywall, eh."
 },
 "The Indoor Recess": {
  "label": "Da Indoor Recess",
  "desc": "At 55 inches of effective rain, nobody rings da bell fer outdoor recess, an' a committee of 9 hall monitors rules it won't get rung till somebody can see da ground again. Nobody's seen da ground in 14 months, ya know. Indoor Recess gets declared permanent, da gym gets cut up into 212 fort lots of 64 square feet, an' da lost-and-found gets nationalized as a strategic cushion reserve holdin' 1,140 items, mostly choppers an' mittens."
 },
 "The Recess Charter": {
  "label": "Da Recess Charter",
  "desc": "Da permanent Indoor Recess adopts a written charter of 31 articles, copied by hand onto 7 sheets of construction paper an' ratified by a show of 4,600 hands. Article 1 guarantees every citizen a pillow. Article 2 guarantees dat pillow's gonna get fluffed. Article 31, added after 3 days of debate, says nobody sits on anybody else's fort, not even to tie a shoe, eh."
 },
 "Pillow Feudalism": {
  "label": "Pillow Feudalism, Eh",
  "desc": "Land's held in pillows now. A lord wit' 40 pillows owes da crown 6 pillows a year an' a knight's service of 2 pillow fights, done by da rules; a serf holds 1 pillow an' da right to rest a head on it fer 8 hours. Enclosure starts when one household claims 3 sectional sofas an' da ottoman, an' 900 smallholders get pushed off onto beanbags."
 },
 "The Cushion Guilds": {
  "label": "Da Cushion Guilds",
  "desc": "Cushion-makin' goes over to da guilds, an' nobody can sell a cushion dat a master hasn't sat on fer 7 days straight. An apprentice spends 4 years learnin' to plump, 3 years learnin' to tuck, an' 1 year learnin' when not to flip a cushion over to hide a stain. Da Guild of Sofa Wrights, 2,300 members strong, controls all 12,000 cushions in da district an' has never once admitted a cushion is lumpy."
 },
 "The Duvet Accords": {
  "label": "Da Duvet Accords",
  "desc": "After 19 months of blanket-hoggin' fights, delegates from 38 households sign da Duvet Accords at a table built outta nothin' but couch cushions. Da Accords set da minimum overhang on each side of a shared bed at 11 inches, outlaw da cocoon move after 10 p.m., an' set up a neutral zone right down da middle of every mattress. 2 signers fall asleep durin' da signin', an' dat goes in da record as unanimous consent."
 },
 "The Blanket Enshrined": {
  "label": "Da Blanket Enshrined",
  "desc": "Da Blanket gets carried in procession to da Great Linen Closet: a 50-by-60-inch green fleece throw wit' one corner chewed by a dog, last washed 3 years ago on da gentle cycle. It's shown folded in 4, chewed corner showin', behind a curtain dat opens da first day of every month, which is also rainy. Pilgrims wait up to 9 hours to see it, an' 70,000 of 'em have been let to touch da corner."
 },
 "The Nap Calendar": {
  "label": "Da Nap Calendar",
  "desc": "Nobody's seen da sun in 4 years, so da Recess t'rows out da calendar an' reckons time in naps. A day is 3 naps, a week is 20, an' a year is 1,000 naps plus a leap nap every 4th year dat ya can take anywhere ya want. Dates get written as naps since da Declaration of Indoor Recess, an' da present nap is 4,212, which somebody's takin' right now."
 },
 "Blanket Empires": {
  "label": "Blanket Empires",
  "desc": "Da fiefs get pulled togedder into 3 blanket empires: da Fleece Dominion up nort', da Quilted Realm down in da river valleys, an' da Knitted Commonwealth, which crochets anyhow. Togedder dey rule 41 million people an' 2.6 million square miles of floor. Border fights get settled by pullin', an' da frontier moves 14 inches a night on average, always toward whoever's colder."
 },
 "The Standard Blanket": {
  "label": "Da Standard Blanket",
  "desc": "By imperial decree da Blanket becomes da standard unit of area: 1 blanket is 3,000 square inches, or 50 by 60, measured wit' da chewed corner counted in an' filled back by calculation. A standard acre is now 2,090.88 blankets, an' deeds get written in blankets, half-blankets an' corners. A platinum copy's kept at 68 degrees in a sealed drawer, an' da chewed corner on it gets reproduced by 11 licensed dogs."
 },
 "The Cocoa Treasury": {
  "label": "Da Cocoa Treasury",
  "desc": "Money's backed by cocoa, held in a reserve of 80 million mugs kept at exactly 140°F. A mug gets divided into 12 sips, an' da central bank's big fear is marshmallow inflation, which topped out at 9 marshmallows a mug before a reform put da standard back at 3. Counterfeitin' gets ya punished by bein' served cocoa made wit' water instead of milk."
 },
 "The Clothespin Army": {
  "label": "Da Clothespin Army",
  "desc": "Every empire keeps a standin' army armed wit' clothespins, handed out 6 to a soldier in memory of da Fort Plan. Da Fleece Dominion fields 1.2 million troops, da Quilted Realm 900,000, an' da Knitted Commonwealth won't publish a number. Wars get fought by clippin' da enemy's blankets to da furniture, an' ya lose a battle when 50 percent of your side's forts are pinned open to da draft."
 },
 "The Sectional Schism": {
  "label": "Da Sectional Schism",
  "desc": "Da Church of da Cushion splits over whether a sectional sofa is 1 couch or a bunch of 'em. Da Unifiers say da chaise is part of da body; da Detachers say ya can take it off an' sleep on it by itself. Da schism lasts 212 years, turns out 40 rival councils an' 7,000 pamphlets, an' only gets settled when a 6-piece sectional turns out to be a 5-piece wit' a loveseat shoved up against it."
 },
 "The Great Quilt Begun": {
  "label": "Da Great Quilt Gets Started",
  "desc": "Da 3 empires agree to stitch one single quilt, one square per household, every square 1 standard blanket. 18 million squares come in over da first 10 years, an' da Cushion Guilds inspect every seam at 12 stitches to da inch. Da first square's green fleece wit' a corner cut away, an' every guild argues its own square oughta go second."
 },
 "The Quilt Afloat": {
  "label": "Da Quilt Afloat",
  "desc": "Da Great Quilt hits da coast after 90 years an' keeps right on goin' out onto da water, floated on 400,000 inflatable pool mattresses lashed togedder at da corners. Da crossin' covers 3,100 miles an' takes 26 years, an' da stitchin' crews live on da quilt da whole time, so 2 generations get born dat never touched a floor. Dey figure floors are just a rumor, eh."
 },
 "The Pillow Parliament": {
  "label": "Da Pillow Parliament",
  "desc": "A Pillow Parliament of 1,500 seats meets on da quilt, every seat a pillow an' every member layin' down. Debate's limited to how long a nap lasts, about 40 minutes, an' a bill passes if most of 'em are still awake at da end. In 300 years of sessions only 17 bills ever passed, an' every one was a resolution to adjourn."
 },
 "Court of Tucked Corners": {
  "label": "Court o' Tucked Corners",
  "desc": "Blanket law gets written down in 44 volumes by da Court of Tucked Corners, where 9 justices hear cases from inside one king-size fort. Da big rulin' says a blanket over 2 sleepers belongs to both of 'em, but da corner belongs to whoever tucked it. Precedent runs 1,700 years now, an' nobody's ever seen a justice wit'out a blanket, not even in da official portraits."
 },
 "The Long Afternoon": {
  "label": "Da Long Afternoon",
  "desc": "Da rain's been fallin' fer 2,400 years wit' no break longer dan 6 minutes, an' da word outside only survives in da sayin' outside da blanket, meanin' cold. Da last known umbrella's kept in a museum next to 1 rubber boot. Kids get taught da sky's just a real big ceilin' wit' a leak, an' 88 percent of grown-ups agree."
 },
 "The Continental Fort": {
  "label": "Da Continental Fort",
  "desc": "A fort goes up over a whole continent: 4.8 million square miles of quilt held up on 60 million chairs, every chair back 34 inches high, same as da original chairs. Da Clothespin Corps keeps 900 million clips along da eaves. Inside, da climate's held at 71°F, da light's always lamp-colored, an' nobody alive remembers a draft."
 },
 "The Great Quilt": {
  "label": "Da Great Quilt",
  "desc": "Da Great Quilt gets finished after 3,600 years: 7 continents joined at da seams, 57 million square miles of patchwork, an' 1 unbroken hem around da whole t'ing. Every square's still exactly 1 standard blanket. Da last stitch gets put in by a kid of 6 picked by lot, an' da planet's formally declared tucked in."
 },
 "Planetary Cozy Order": {
  "label": "Planetary Cozy Order",
  "desc": "One Planetary Cozy Order runs 11 billion people, every one of 'em indoors an' 94 percent of 'em layin' down at any given time. Da constitution's 1 sentence long: Nobody's gotta get up. Da whole government's 400 million pillow clerks whose main job is fluffin' each udder, an' da capital moves every night to wherever da best nap got reported."
 },
 "The Last Door": {
  "label": "Da Last Door",
  "desc": "Da last door to da outside gets shut after 5,000 years of standin' just a little bit open, an' a draft snake 26 feet long gets laid along da threshold. Every udder openin' on da planet's already been quilted over. Dey hold a ceremony of 3 knocks dere once every 1,000 naps, an' nobody on eider side answers, 'cause dere's nobody on da udder side."
 },
 "Orbital Forts": {
  "label": "Orbital Forts",
  "desc": "Da first orbital fort goes up 250 miles: 2 chairs welded to a pressure hull, 4 cushions, an' a blanket stretched over da whole works against 1 sunrise every 90 minutes. In 300 years dere's 16,000 of 'em, ringed around da planet like a comforter dat's slid halfway off da bed. Crews sleep in shifts, 'cause somebody's always gotta be awake to tuck da udders in."
 },
 "The Lunar Pillow": {
  "label": "Da Moon Pillow",
  "desc": "Da moon gets covered in one single pillowcase 14.6 million square miles across, stuffed wit' 40 trillion cubic feet of synthetic down made over 700 years. Seen from da planet, it's exactly da right softness. Da tides are gentler now, an' da Court of Tucked Corners rules, 7 to 2, dat folks can nap on da moon wit'out a permit."
 },
 "The Cushion Belt": {
  "label": "Da Cushion Belt",
  "desc": "Da Cushion Guilds upholster da asteroid belt, 1.1 million bodies every one fitted wit' a slipcover an' assigned a household. Da work takes 2,000 years at an average of 550 slipcovers a year, an' da guild still won't cover da 4 biggest ones 'cause, dey say, dose ain't cushions, dey're ottomans. Da belt turns into da comfiest part of da system, an' da most fought over."
 },
 "The Solar Lampshade": {
  "label": "Da Solar Lampshade",
  "desc": "Da sun gets judged too bright to nap under, so dey fit it wit' a lampshade 1.1 million miles across, pleated in 48 panels of cream-colored sail. Output to da inner planets drops to 60 percent, which is just da settin' of a readin' lamp at bedtime. Da project takes 4,000 years, an' da pull-chain, 93 million miles long, gets left where da capital can reach it."
 },
 "The Blanket Ark": {
  "label": "Da Blanket Ark",
  "desc": "Da Blanket leaves da home world on a generation ship called da Good Dog, kept in a climate-controlled drawer at 68 degrees, chewed corner up. Da trip to da nearest star is 4.2 light-years an' takes 1,900 years, an' 63 generations of crew get born, fold da Blanket once a year fer inspection, an' pass on wit'out ever havin' unfolded it all da way, which is forbidden."
 },
 "The Colony Forts": {
  "label": "Da Colony Forts",
  "desc": "Colony forts go up in 340 star systems, each one built from 1 kit wit' a standard blanket, a pair of chairs an' a pouch of clothespins, an' each one dedicated to a copy of da Blanket wit' da corner chewed by an approved dog. Messages between forts take up to 80 years each way an' are pretty much all da one question, are ya warm enough. In 6,000 years of letters, da answer's always been yah."
 },
 "The Star-System Duvet": {
  "label": "Da Star-System Duvet",
  "desc": "One blanket gets pulled over a whole star system: a fleece membrane 9 billion miles across, 1 fiber t'ick, wit' da star inside it fer a night-light. It holds 8 planets, 212 moons an' about 40 billion residents at a steady 71°F. Da hem's tucked under da system's gravity well, an' da one corner left loose gets chewed ceremonially every 1,000 years."
 },
 "The Chewed Corner Doctrine": {
  "label": "Da Chewed Corner Doctrine",
  "desc": "A council of 212 systems argues fer 3,000 years over whether a perfect blanket oughta have 4 corners, or 3 an' a chew. Da Doctrine of da Chewed Corner wins by 1 vote: a blanket ain't complete till somethin's loved it enough to ruin it a little. After dat, blankets get made wit' da corner already missin', an' da 14 heretic systems dat insist on 4 good corners get treated wit' pity, not force."
 },
 "The Galactic Quilt": {
  "label": "Da Galactic Quilt",
  "desc": "Da colony forts get stitched togedder across da galactic arm into a quilt 12,000 light-years long, every patch a star system an' every seam a supply lane patrolled by da Clothespin Corps. It takes 90,000 years. Dere's 4 million patches, an' when dey finally get joined, da quilt comes up 1 blanket short of coverin' da arm, which da guilds blame on shrinkage in da wash."
 },
 "The Long Nap": {
  "label": "Da Long Nap",
  "desc": "Da galaxy goes into da Long Nap, a sleep stretch of 250 million years timed to 1 trip of da galaxy around its core. Duty officers stay awake in 1 fort per 10,000 systems to fiddle wit' da thermostat an' turn da pages of books nobody's readin'. Da nap calendar counts it as one single nap, number 91 billion, an' da Pillow Parliament's motion to stretch it 5 more minutes passes unanimous."
 },
 "The Local Group Comforter": {
  "label": "Da Local Group Comforter",
  "desc": "Da comforter gets stretched past da galaxy out to da local group, 54 galaxies under one single cover 10 million light-years wide. Fillin' it takes 6 quintillion tons of down, an' da Cushion Guilds, 2 trillion members strong now, spend 40 million years arguin' about thread count before settlin' on 400, da number on da original sheets. Da gaps between galaxies get declared da cold side of da bed, an' nobody gets assigned to 'em."
 },
 "The Quilted Web": {
  "label": "Da Quilted Web",
  "desc": "After 900 million years of surveyin', da cosmic web gets recognized as quiltin': filaments are seams, voids are patches, an' da whole t'ing's 93 billion light-years across wit' 2 trillion galaxies sewn in at about 1 per stitch. Da guilds won't say dey made it. Dey just point out da stitchin's 12 to da inch, da old standard, an' dat somebody somewhere musta been awful cold."
 },
 "The Thermostat Hearings": {
  "label": "Da Thermostat Hearin's",
  "desc": "Da universe starts coolin' toward da end, an' da Court of Tucked Corners hears Everybody v. da Second Law of Thermodynamics over 10 billion years. Da defendant never shows up. Judgment gets entered by default an' da Court orders da universe held at 71°F; da order gets ignored, da background drops to 1 degree above absolute zero, an' all 9 justices file a dissent against da temperature itself."
 },
 "The Last Hearth": {
  "label": "Da Last Hearth",
  "desc": "Da stars go out at 1 a century, den 1 a millennium, an' den dere's 3 left, an' da cozy order gadders round 'em like a family gadders round da woodstove at camp. Da last star's a red dwarf 0.1 da mass of da sun, figured to burn fer 10 trillion years. Its surface is 4,000°F, an' every fort still standin' faces it, wit' wool socks dryin' on da chairs."
 },
 "Folding Up": {
  "label": "Foldin' Up",
  "desc": "Wit' da last star out, forts come down 1 at a time an' deir blankets get folded into da forts dat are left, 4 into 1 an' den 4 into 1 again, fer 100 trillion years. Cushions get stacked, chairs pushed in, clothespins put back in da bag in 6s. By da end 1 fort's standin', an' 1 flashlight's on, runnin' on its last 2 batteries, da only light left anywhere."
 },
 "The Last Cozy Thing": {
  "label": "Da Last Cozy T'ing",
  "desc": "Da flashlight goes out, da fort's last chair gets put back in a kitchen dat don't exist anymore, an' da Blanket's da only object left in da universe: 50 by 60 inches, green fleece, 1 corner chewed by a dog. Every atom of everyt'ing else has decayed, which took 10 to da 100th years an' never touched it. It ain't warm, eider. It's just still da Blanket, an' da chewed corner's still chewed."
 },
 "Measure of Everything": {
  "label": "Measure o' Everyt'ing",
  "desc": "Wit' nothin' else to compare it to, da Blanket's da unit, da t'ing bein' measured, an' da whole measurement all at once. Da dark around it gets recorded as 3,000 square inches of blanket an' some unknown amount of not-blanket. Its temperature gets recorded same as it was on da couch, give or take 1 degree. Da last entry in da ledger, 1 line long, says: 1 blanket, 50 by 60, chewed."
 },
 "Six Clothespins": {
  "label": "Six Clothespins, Yah",
  "desc": "At nearly 30,000 inches da design hits its final form, an' it turns out to be da drawin' from da first rainy afternoon, on da back of a cereal box, unchanged: 4 cushions, 2 chairs, 1 blanket, 6 clothespins. Da cushions are galaxies now, da chairs are da 2 walls of a void 400 million light-years deep, an' da blanket is da Blanket, still 50 by 60 inches, which turns out to be enough. No amount of comfort ever came up wit' a reason fer a sevent' clothespin."
 },
 "Five More Minutes": {
  "label": "Five More Minutes, Eh",
  "desc": "Da scale runs outta names at 30,000 inches, an' da rain, wherever it's fallin', keeps on fallin'. Whatever's goin' on under da Blanket quit matchin' da definition of a blanket fort somethin' like 10 to da 100th years ago, an' nobody's come to take it down. Somewhere under da chewed corner, somebody asks fer 5 more minutes. Da request gets granted, an' how long it lasts gets reported as unbounded."
 }
});
window.YOOPER.COZY_WAR_BANDS = Object.assign(window.YOOPER.COZY_WAR_BANDS || {}, {
 "Rainy Day": "Rainy Day at Camp",
 "High Water": "High Water, Eh",
 "Beyond the Weather": "Holy Wah, Past Da Weather"
});
